import {renderSchemaForm,schemaFields} from './schema-form.js';
import {proposalInput,applyAgentProposal} from './setup-agent.js';

const ENVIRONMENT=new Set(['seeds','town','housing','weather']);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mergeValues(base,patch){const out=structuredClone(base||{});for(const [k,v] of Object.entries(patch||{}))out[k]=v&&typeof v==='object'&&!Array.isArray(v)?mergeValues(out[k],v):structuredClone(v);return out;}
export function inStage(scope,stage,key,group){return scope==='town'?group['x-applies']!=='run'&&(stage===0?ENVIRONMENT.has(key):!ENVIRONMENT.has(key)):stage===1;}
const bucket=scope=>scope==='town'?'townOverrides':scope==='run'?'settings':'operations';
export function replaceStageOverrides(draft,scope,stage,values,schema){const next=structuredClone(draft[bucket(scope)]||{});for(const f of schemaFields(schema,{groups:(key,g)=>inStage(scope,stage,key,g)}))delete next[f.group];draft[bucket(scope)]={...next,...values};}
export function applyRegion(draft,region){return {...draft,environmentProfile:region.id,region:region.name,townOverrides:mergeValues(draft.townOverrides,region.overrides),configDirty:true,agentSummaryDirty:!!draft.agentProposal};}
export function wizardDraft(draft,packs){const next=structuredClone(draft);if(next.wizardVersion!==2)next.step=next.step>=3?2:next.step===2?1:0;next.wizardVersion=2;
 if(!next.preset){const t=packs?.towns?.find(t=>t.preset==='small_town')||packs?.towns?.[0];if(t)Object.assign(next,{preset:t.preset,townRef:t.preset,townId:t.townId,townName:t.preset.replaceAll('_',' '),homes:t.homes});}
 next.townOverrides||={};next.settings||={};next.operations||={};return next;
}
export function setupProposal(draft){return {...proposalInput(draft),name:draft.name.trim(),summary:draft.summary||'Review your environment, utility and operating assumptions.',assumptions:draft.assumptions||[],limitations:draft.limitations||[]};}
export function acceptSetup(draft,p){return {...applyAgentProposal(draft,p),scenarioId:draft.scenarioId,scenarioTitle:draft.scenarioTitle,step:2,wizardVersion:2,configDirty:false,agentSummaryDirty:false};}
const at=(value,path)=>path.split('.').reduce((o,k)=>o?.[k],value);
function input(scope,path,label,{min=0,max=200,step=1,note='',suffix=''}={}){return `<label>${label}${suffix?` <span>${suffix}</span>`:''}<input type="number" data-basic-scope="${scope}" data-basic-path="${path}" min="${min}" max="${max}" step="${step}" required></label>${note?`<p class="field-note">${note}</p>`:''}`;}
export function stageMarkup(stage,data,draft){if(!data)return '<div class="help-card" role="status">Loading the engine’s setup settings…</div>';
 const advanced=`<details class="setup-advanced" id="stage-advanced" ${draft.advanced?.[stage]?'open':''}><summary><span>Advanced ${stage===0?'environment':'utility & operations'} settings</span><small>Browse every setting for this stage</small></summary><div class="advanced-body"><label class="sr-only" for="advanced-filter">Find a setting</label><input id="advanced-filter" type="search" placeholder="Find a setting, e.g. ${stage===0?'pools or temperature':'crew, billing or meter'}"><p class="field-note">Use ⓘ for an input’s effect and limits. Basic and advanced controls edit the same values. Fraction fields use 0–1 (0.15 = 15%).</p>${(stage===0?['town']:['town','run']).map(scope=>`<section><h3 class="advanced-section-title">${scope==='town'?(stage===0?'Town, households & weather':'Utility networks & town defaults'):scope==='run'?'Year staffing & workflow':'Map-day operations'}</h3>${scope==='operations'?'<p class="field-note">These controls govern the map’s operations day. Year field staffing and workloads are above.</p>':''}<div data-config-scope="${scope}"></div></section>`).join('')}${stage===1?'<details id="map-defaults-panel" class="map-defaults-panel"><summary>Map-day operations</summary><p class="field-note">These controls govern the map’s operations day. Defaults follow your town settings; Year field staffing is above.</p><div data-config-scope="operations"></div></details>':''}</div></details>`;
 if(stage===0)return `<div class="setup-basic-grid">${input('town','town.houses','How many homes?',{min:20,max:data.homeLimit,step:1})}<label>Regional starting point<select id="setup-region-profile"><option value="custom">Custom / keep current values</option>${data.regions.map(r=>`<option value="${esc(r.id)}" ${draft.environmentProfile===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label></div><p class="field-note">Homes are residential premises; shops and other sites add customer accounts. This engine supports up to ${data.homeLimit.toLocaleString()} homes.</p><label for="setup-region">Location / service area <span>Optional</span></label><input id="setup-region" maxlength="200" value="${esc(draft.region||'')}" placeholder="e.g. Albany suburbs, New York"><p class="field-note">The regional starting point sets weather and housing assumptions. The service-area name is a label you can refine.</p><div id="environment-preview" class="environment-preview" aria-live="polite"></div><p class="field-note">${esc(data.regionalNote)}</p>${advanced}`;
 return `<label for="setup-services">Services in this town</label><select id="setup-services"><option value="mixed">Electricity + water + gas districts</option><option value="electric">Electricity + water · all-electric heating</option></select><p class="field-note">Electricity and water serve every town. Gas availability varies by district; Advanced lets you adjust its coverage.</p><div class="setup-basic-grid">${input('run','process.analysts','Billing analysts')}${input('run','contact.agents','Contact-centre agents')}${input('run','field.crew_meter.per_1000_premises','Meter technicians',{max:20,step:'any',suffix:'crews / 1,000 premises'})}${input('run','field.crew_emergency.per_1000_premises','On-call responders',{max:20,step:'any',suffix:'crews / 1,000 premises'})}</div><p class="field-note">Year field crews scale with total premises, including commercial sites. A fraction represents part of a crew’s time. Advanced includes electric, water, gas and construction crews, work types and costs.</p>${advanced}`;
}

export function installStageControls({root,stage,data,getDraft,onChange,onRegion,onError,getOperationDefaults}){
 if(!data)return {invalid:()=>true};
 const forms={},values={};
 for(const scope of stage===0?['town']:['town','run']){
  values[scope]=mergeValues(data.defaults[scope],getDraft()[bucket(scope)]);
  forms[scope]=renderSchemaForm(root.querySelector(`[data-config-scope="${scope}"]`),data.schemas[scope],{
   values:values[scope],base:data.defaults[scope],groups:(key,g)=>inStage(scope,stage,key,g),showAdvanced:true,collapsible:true,open:[],baseLabel:'Starting town',
   onChange:overrides=>{replaceStageOverrides(getDraft(),scope,stage,overrides,data.schemas[scope]);onChange();syncBasic();if(scope==='town'&&root.querySelector('#map-defaults-panel'))root.querySelector('#map-defaults-panel').open=false;}
  });
 }
 function syncBasic(){for(const el of root.querySelectorAll('[data-basic-path]')){if(document.activeElement===el)continue;el.value=at(forms[el.dataset.basicScope].values,el.dataset.basicPath)??'';}
  const services=root.querySelector('#setup-services');if(services)services.value=forms.town.values.gas?.all_electric_district_share===1?'electric':'mixed';
  const preview=root.querySelector('#environment-preview');if(preview){const {weather:w,housing:h,town:t}=forms.town.values;const profile=data.regions.find(r=>r.id===getDraft().environmentProfile);preview.innerHTML=`<strong>${esc(profile?.name||'Your environment')}</strong><p>${esc(profile?.description||'Adjust the town, housing and weather in Advanced.')}</p><dl><div><dt>Winter / summer mean</dt><dd>${esc(w.winter.mean_c)}°C / ${esc(w.summer.mean_c)}°C</dd></div><div><dt>Pool share on eligible lots</dt><dd>${Math.round(h.pool_rate*1000)/10}%</dd></div><div><dt>Construction era</dt><dd>Centre ${esc(t.era_core_year)} · +${esc(t.era_span_years)} years toward the edge</dd></div><div><dt>Two-storey homes by era</dt><dd>${Object.values(h.two_storey_share).map(v=>Math.round(v*100)+'%').join(' / ')}</dd></div></dl><p class="field-note">Two-storey shares: pre-1945 / post-war / modern. Values shown include your edits.</p>`;}
 }
 function set(scope,path,value){const [group,key,child]=path.split('.');forms[scope].set(group+'.'+key,child?{...forms[scope].values[group][key],[child]:value}:value);}
 for(const el of root.querySelectorAll('[data-basic-path]'))el.onchange=()=>{if(!el.checkValidity()){el.setAttribute('aria-invalid','true');return;}el.removeAttribute('aria-invalid');set(el.dataset.basicScope,el.dataset.basicPath,Number(el.value));};
 const services=root.querySelector('#setup-services');if(services)services.onchange=()=>set('town','gas.all_electric_district_share',services.value==='electric'?1:.15);
 const region=root.querySelector('#setup-region-profile');if(region)region.onchange=()=>{if(Object.values(forms).some(f=>f.invalid())){region.value=getDraft().environmentProfile||'custom';onError('Fix the highlighted settings before changing region.');return;}const r=data.regions.find(r=>r.id===region.value);onRegion(r);};
 const map=root.querySelector('#map-defaults-panel');let mapPending=false,mapFailed=false,mapRevision=0;
 if(map)map.ontoggle=async()=>{const revision=++mapRevision;if(!map.open)return;if(forms.operations?.invalid()){onError('Fix the highlighted map settings first.');return;}mapPending=true;mapFailed=false;const box=map.querySelector('[data-config-scope]');box.innerHTML='<p class="field-note" role="status">Loading defaults from your environment…</p>';
  try{const defaults=await getOperationDefaults();if(revision!==mapRevision||!root.contains(map))return;
   forms.operations=renderSchemaForm(box,data.schemas.operations,{values:mergeValues(defaults,getDraft().operations),base:defaults,showAdvanced:true,collapsible:true,open:[],baseLabel:'Your town',onChange:overrides=>{getDraft().operations=overrides;onChange();}});
   forms.operations.filter(root.querySelector('#advanced-filter').value);
  }catch(e){if(revision!==mapRevision||!root.contains(map))return;mapFailed=true;box.textContent='Could not load map-day defaults. Close and reopen this section to retry.';onError(e.message);}finally{if(revision===mapRevision)mapPending=false;}
 };
 root.querySelector('#advanced-filter').oninput=e=>{for(const form of Object.values(forms))form.filter(e.target.value);};
 root.querySelector('#stage-advanced').ontoggle=e=>{(getDraft().advanced||={})[stage]=e.target.open;onChange(false);};
 root.querySelector('#stage-advanced').addEventListener('click',e=>{const b=e.target.closest('.schema-info');if(!b)return;e.preventDefault();const row=b.closest('.has-pop'),open=!row.classList.contains('is-open');row.classList.toggle('is-open',open);b.setAttribute('aria-expanded',String(open));});
 syncBasic();
 return {invalid:()=>!!(map?.open&&(mapPending||mapFailed))||Object.values(forms).some(f=>f.invalid())||[...root.querySelectorAll('[data-basic-path]')].some(i=>!i.checkValidity()),forms};
}
